// Genera los .xlsx de prueba armados a mano que imitan cómo escriben el XML Excel y Google Sheets (no son
// exportaciones de esos programas: acá no se pueden correr). catalogo-libreoffice.xlsx sí es una
// exportación real de LibreOffice (desde catalogo-libreoffice.fods con soffice --convert-to xlsx).
// Si se suma una exportación real de Excel o Sheets, va junto a estos y se agrega a xlsx-reader.test.ts.
// Datos inventados. Uso: npx tsx test/fixtures/catalog/build-xlsx-fixtures.ts
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { strToU8, zipSync } from 'fflate';

const DIR = import.meta.dirname;
const XML = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';

const CONTENT_TYPES = `${XML}<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/sharedStrings.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>`;
const ROOT_RELS = `${XML}<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`;

function write(name: string, files: Record<string, string>): void {
  const zip = zipSync(Object.fromEntries(Object.entries(files).map(([path, xml]) => [path, strToU8(xml)])));
  writeFileSync(join(DIR, name), zip);
}

// ---- Estilo Excel ----------------------------------------------------------------------------------------
// Strings compartidos con corridas de formato (r/rPr) y guía fonética (rPh), entidades, fecha con formato
// predefinido 14 y con uno propio, moneda con formato propio, fórmula con valor guardado, error #N/A,
// huecos en columnas y filas, celdas combinadas (título y categoría en vertical) y dos hojas.
write('catalogo-estilo-excel.xlsx', {
  '[Content_Types].xml': CONTENT_TYPES,
  '_rels/.rels': ROOT_RELS,
  'xl/workbook.xml': `${XML}<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" mc:Ignorable="x15 xr xr6 xr10 xr2" xmlns:x15="http://schemas.microsoft.com/office/spreadsheetml/2010/11/main" xmlns:xr="http://schemas.microsoft.com/office/spreadsheetml/2014/revision"><fileVersion appName="xl" lastEdited="7" lowestEdited="7" rupBuild="28526"/><workbookPr defaultThemeVersion="202300"/><bookViews><workbookView xWindow="-120" yWindow="-120" windowWidth="29040" windowHeight="15720"/></bookViews><sheets><sheet name="Lista" sheetId="1" r:id="rId1"/><sheet name="Otra hoja" sheetId="2" r:id="rId2"/></sheets><calcPr calcId="191029"/></workbook>`,
  'xl/_rels/workbook.xml.rels': `${XML}<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId4" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings" Target="sharedStrings.xml"/></Relationships>`,
  'xl/styles.xml': `${XML}<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" mc:Ignorable="x14ac x16r2 xr" xmlns:x14ac="http://schemas.microsoft.com/office/spreadsheetml/2009/9/ac"><numFmts count="2"><numFmt numFmtId="164" formatCode="&quot;$&quot;\\ #,##0"/><numFmt numFmtId="165" formatCode="dd/mm/yyyy;@"/></numFmts><fonts count="1"><font><sz val="11"/><name val="Aptos Narrow"/></font></fonts><fills count="1"><fill><patternFill patternType="none"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="5"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="14" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/><xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/><xf numFmtId="165" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/><xf numFmtId="4" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs></styleSheet>`,
  'xl/sharedStrings.xml': `${XML}<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="16" uniqueCount="14"><si><t>Lista de precios (inventada)</t></si><si><t>Código</t></si><si><t>Descripción</t></si><si><t>Rubro</t></si><si><t>Unidad</t></si><si><t>M2 x caja</t></si><si><t>Precio</t></si><si><t>Link</t></si><si><t>Fecha alta</t></si><si><t>CER-001</t></si><si><r><rPr><b/><sz val="11"/></rPr><t xml:space="preserve">Cerámica </t></r><r><rPr><sz val="11"/></rPr><t>Símil Madera Roble 45x45</t></r><rPh sb="0" eb="1"><t>セラミック</t></rPh></si><si><t>Cerámicos</t></si><si><t>m2</t></si><si><t>Pegamento &amp; pastina &lt;gris&gt;</t></si></sst>`,
  'xl/worksheets/sheet1.xml': `${XML}<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" mc:Ignorable="x14ac xr xr2 xr3" xmlns:x14ac="http://schemas.microsoft.com/office/spreadsheetml/2009/9/ac"><dimension ref="A1:H7"/><sheetViews><sheetView tabSelected="1" workbookViewId="0"/></sheetViews><sheetFormatPr defaultRowHeight="15" x14ac:dyDescent="0.25"/><sheetData><row r="1" spans="1:8" x14ac:dyDescent="0.25"><c r="A1" t="s"><v>0</v></c></row><row r="3" spans="1:8"><c r="A3" t="s"><v>1</v></c><c r="B3" t="s"><v>2</v></c><c r="C3" t="s"><v>3</v></c><c r="D3" t="s"><v>4</v></c><c r="E3" t="s"><v>5</v></c><c r="F3" t="s"><v>6</v></c><c r="G3" t="s"><v>7</v></c><c r="H3" t="s"><v>8</v></c></row><row r="4" spans="1:8"><c r="A4" t="s"><v>9</v></c><c r="B4" t="s"><v>10</v></c><c r="C4" t="s"><v>11</v></c><c r="D4" t="s"><v>12</v></c><c r="E4" s="4"><v>2.0200000000000001</v></c><c r="F4" s="2"><v>37290</v></c><c r="G4" t="str"><f>"https://www.ceramicos-del-sur.test/p/"&amp;LOWER(A4)</f><v>https://www.ceramicos-del-sur.test/p/cer-001</v></c><c r="H4" s="1"><v>46096</v></c></row><row r="5" spans="1:8"><c r="A5"><v>12345</v></c><c r="B5" t="s"><v>13</v></c><c r="D5" t="s"><v>12</v></c><c r="F5" s="2"><f>F4*0.3</f><v>11187</v></c><c r="G5" t="e"><v>#N/A</v></c><c r="H5" s="3"><v>46100</v></c></row><row r="7" spans="1:8"><c r="A7" t="b"><v>1</v></c><c r="C7"/></row></sheetData><mergeCells count="2"><mergeCell ref="A1:D1"/><mergeCell ref="C4:C5"/></mergeCells><pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/></worksheet>`,
  'xl/worksheets/sheet2.xml': `${XML}<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="A1" t="s"><v>3</v></c><c r="B1"><v>42</v></c></row></sheetData></worksheet>`,
});

// ---- Estilo Google Sheets --------------------------------------------------------------------------------
// Strings compartidos sin corridas, fecha con formato propio "d/m/yyyy", números con muchos decimales y una
// hoja que no es la primera. Las referencias van completas.
write('catalogo-estilo-google-sheets.xlsx', {
  '[Content_Types].xml': CONTENT_TYPES,
  '_rels/.rels': ROOT_RELS,
  'xl/workbook.xml': `${XML}<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><workbookPr/><sheets><sheet state="visible" name="Portada" sheetId="1" r:id="rId4"/><sheet state="visible" name="Catálogo" sheetId="2" r:id="rId5"/></sheets><definedNames/><calcPr/></workbook>`,
  'xl/_rels/workbook.xml.rels': `${XML}<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" Target="theme/theme1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings" Target="sharedStrings.xml"/><Relationship Id="rId4" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId5" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/></Relationships>`,
  'xl/styles.xml': `${XML}<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:x14ac="http://schemas.microsoft.com/office/spreadsheetml/2009/9/ac" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006"><numFmts count="1"><numFmt numFmtId="164" formatCode="d/m/yyyy"/></numFmts><fonts count="1"><font><sz val="10.0"/><name val="Arial"/></font></fonts><fills count="1"><fill><patternFill patternType="none"/></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf borderId="0" fillId="0" fontId="0" numFmtId="0" applyAlignment="1" applyFont="1"/></cellStyleXfs><cellXfs count="2"><xf borderId="0" fillId="0" fontId="0" numFmtId="0" xfId="0" applyAlignment="1" applyFont="1"/><xf borderId="0" fillId="0" fontId="0" numFmtId="164" xfId="0" applyAlignment="1" applyFont="1" applyNumberFormat="1"/></cellXfs></styleSheet>`,
  'xl/sharedStrings.xml': `${XML}<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="10" uniqueCount="10"><si><t>Portada</t></si><si><t>sku</t></si><si><t>nombre</t></si><si><t>url</t></si><si><t>m2 por caja</t></si><si><t>precio</t></si><si><t>alta</t></si><si><t>POR-010</t></si><si><t>Porcelanato Nórdico Gris 60x60</t></si><si><t>https://ceramicos-del-sur.test/p/por-010</t></si></sst>`,
  'xl/worksheets/sheet1.xml': `${XML}<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="A1" s="0" t="s"><v>0</v></c></row></sheetData></worksheet>`,
  'xl/worksheets/sheet2.xml': `${XML}<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheetPr><outlinePr summaryBelow="0" summaryRight="0"/></sheetPr><sheetViews><sheetView workbookViewId="0"/></sheetViews><sheetFormatPr customHeight="1" defaultColWidth="12.63" defaultRowHeight="15.75"/><sheetData><row r="1"><c r="A1" s="0" t="s"><v>1</v></c><c r="B1" s="0" t="s"><v>2</v></c><c r="C1" s="0" t="s"><v>3</v></c><c r="D1" s="0" t="s"><v>4</v></c><c r="E1" s="0" t="s"><v>5</v></c><c r="F1" s="0" t="s"><v>6</v></c></row><row r="2"><c r="A2" s="0" t="s"><v>7</v></c><c r="B2" s="0" t="s"><v>8</v></c><c r="C2" s="0" t="s"><v>9</v></c><c r="D2" s="0"><v>1.4399999999999999</v></c><c r="E2" s="0"><v>45990.5</v></c><c r="F2" s="1"><v>46096.0</v></c></row></sheetData><drawing r:id="rId1"/></worksheet>`,
});

// ---- Otros generadores -----------------------------------------------------------------------------------
// Strings en línea (inlineStr), prefijo de namespace (x:), destinos absolutos en las relaciones, celdas sin
// referencia (posición por orden), sin sharedStrings ni styles.
write('catalogo-inline-sin-referencias.xlsx', {
  '[Content_Types].xml': CONTENT_TYPES,
  '_rels/.rels': ROOT_RELS,
  'xl/workbook.xml': `${XML}<x:workbook xmlns:x="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><x:sheets><x:sheet name="Hoja1" sheetId="1" r:id="R1"/></x:sheets></x:workbook>`,
  'xl/_rels/workbook.xml.rels': `${XML}<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="R1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="/xl/worksheets/sheet1.xml"/></Relationships>`,
  'xl/worksheets/sheet1.xml': `${XML}<x:worksheet xmlns:x="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><x:sheetData><x:row><x:c t="inlineStr"><x:is><x:t>Código</x:t></x:is></x:c><x:c t="inlineStr"><x:is><x:t>Nombre</x:t></x:is></x:c><x:c t="inlineStr"><x:is><x:t>Precio</x:t></x:is></x:c></x:row><x:row><x:c t="inlineStr"><x:is><x:r><x:t xml:space="preserve">PEG-</x:t></x:r><x:r><x:t>100</x:t></x:r></x:is></x:c><x:c t="inlineStr"><x:is><x:t>Pegamento para porcelanato 30 kg</x:t></x:is></x:c><x:c><x:v>9800</x:v></x:c></x:row></x:sheetData></x:worksheet>`,
});

console.log('Fixtures generados en', DIR);
